function status(m){$("lst").textContent=m}
function addLangOption(name){const sel=$("lang");if(![...sel.options].some(o=>o.value===name)){const o=document.createElement("option");o.value=name;o.textContent=name;const ot=sel.querySelector('[value="__other"]');sel.insertBefore(o,ot||null)}sel.value=name}
function addOther(){const sel=$("lang");if(sel.querySelector('[value="__other"]'))return;const o=document.createElement("option");o.value="__other";o.textContent="Other language…";sel.appendChild(o)}
async function customLang(name){name=name.trim();if(!name||!SAMPLE)return;status("Translating…");
let d=null;try{d=JSON.parse(lsGet("im-dict-"+name)||"null")}catch(e){}
if(!d){try{d=await SAMPLE.json("Translate each of these English UI strings from a mobile-game hero database website into "+name+". Keep placeholders such as {n} or {a} exactly as written, keep symbols like \u00b7 \u2190 \u2026 and numbers, and keep proper nouns as they are. Return one JSON object mapping each English string, exactly as given, to its translation.\n\n"+JSON.stringify(VKEYS));
if(!d||typeof d!=="object")throw 0;lsSet("im-dict-"+name,JSON.stringify(d))}catch(e){status("Translation unavailable. Sign in and allow Claude access, or try again.");$("lang").value=LANG;return}}
DICT[name]=d;addLangOption(name);$("langx").hidden=true;lsSet("im-lang",name);setLang(name,true)}
async function kitCustom(hn){if(LANG==="en"||(LANG==="ru"&&!KT[hn].xl)||!SAMPLE||!KT[hn])return;const key=LANG+"|"+hn;if(KTC[key])return;
let c=null;try{c=JSON.parse(lsGet("im-kit-"+key)||"null")}catch(e){}
const lang=LANG;
if(!c){status("Translating kit…");try{c=await SAMPLE.json("Translate these hero skill descriptions of a mobile game into "+lang+". Keep numbers, percentages, [bracketed] effect names, hero names and skill names recognisable (you may add a translation in brackets after a bracketed name). Return a JSON array with exactly the same length and shape, translating only the string values of s and of each entry in e.\n\n"+JSON.stringify(KT[hn].sk.map(q=>({s:q.s,e:q.e||{}})).concat(KT[hn].xl?[{s:"",e:KT[hn].xl}]:[])));
if(!Array.isArray(c)||c.length!==KT[hn].sk.length+(KT[hn].xl?1:0))throw 0;lsSet("im-kit-"+key,JSON.stringify(c))}catch(e){status("Kit translation unavailable.");return}}
KTC[key]=c;status("");if(LANG===lang&&CUR===hn&&!$("detail").hidden)show(hn,true)}
